// Do not edit this file as it will be overwritten if HAMR codegen is rerun

//! The GUMBO contract checks of every thread: IEP_Post at initialization, CEP_Pre
//! when a thread is about to be dispatched, and CEP_Post when it completes, against
//! the pre-state saved at dispatch.

use data::*;
use crate::{Event, SystemView, ViolationSink};
use crate::gumbox::gen_gen_containers::*;
use crate::gumbox::splitter_splitter_containers::*;
use crate::gumbox::incx_incx_containers::*;
use crate::gumbox::clampx_clampx_containers::*;
use crate::gumbox::decy_decy_containers::*;
use crate::gumbox::merger_merger_containers::*;
use crate::gumbox::consume_consume_containers::*;

pub struct ComponentContracts {
  pre_gen_gen: Option<PreState_gen_gen>,
  pre_ok_gen_gen: bool,
  pre_splitter_splitter: Option<PreState_splitter_splitter>,
  pre_ok_splitter_splitter: bool,
  pre_incx_incx: Option<PreState_incx_incx>,
  pre_ok_incx_incx: bool,
  pre_clampx_clampx: Option<PreState_clampx_clampx>,
  pre_ok_clampx_clampx: bool,
  pre_decy_decy: Option<PreState_decy_decy>,
  pre_ok_decy_decy: bool,
  pre_merger_merger: Option<PreState_merger_merger>,
  pre_ok_merger_merger: bool,
  pre_consume_consume: Option<PreState_consume_consume>,
  pre_ok_consume_consume: bool,
}

impl ComponentContracts {
  pub const fn new() -> Self {
    ComponentContracts {
      pre_gen_gen: None,
      pre_ok_gen_gen: true,
      pre_splitter_splitter: None,
      pre_ok_splitter_splitter: true,
      pre_incx_incx: None,
      pre_ok_incx_incx: true,
      pre_clampx_clampx: None,
      pre_ok_clampx_clampx: true,
      pre_decy_decy: None,
      pre_ok_decy_decy: true,
      pre_merger_merger: None,
      pre_ok_merger_merger: true,
      pre_consume_consume: None,
      pre_ok_consume_consume: true,
    }
  }

  /// Initialization guarantees, checked once every thread has initialized and
  /// before any has computed.
  pub fn on_init<V: SystemView, S: ViolationSink>(&mut self, s: &mut V, out: &mut S) {
    {
      s.focus(Some(crate::Thread::gen_gen));
      let post_gen_gen = PostState_gen_gen {
        api_outstruct: s.get_gen_gen_outstruct(),
      };
      if s.missing() {
        out.report(crate::Event::CheckSkipped { thread: "gen_gen", check: "IEP_Post" });
      } else if !crate::gumbox::gen_gen_GUMBOX::initialize_IEP_Post(
        post_gen_gen.api_outstruct) {
        out.report(crate::Event::IepPostViolation { thread: "gen_gen", post: &post_gen_gen });
      }
    }
    {
      s.focus(Some(crate::Thread::splitter_splitter));
      let post_splitter_splitter = PostState_splitter_splitter {
        api_xfield: s.get_splitter_splitter_xfield(),
        api_yfield: s.get_splitter_splitter_yfield(),
      };
      if s.missing() {
        out.report(crate::Event::CheckSkipped { thread: "splitter_splitter", check: "IEP_Post" });
      } else if !crate::gumbox::splitter_splitter_GUMBOX::initialize_IEP_Post(
        post_splitter_splitter.api_xfield, post_splitter_splitter.api_yfield) {
        out.report(crate::Event::IepPostViolation { thread: "splitter_splitter", post: &post_splitter_splitter });
      }
    }
    {
      s.focus(Some(crate::Thread::consume_consume));
      let post_consume_consume = PostState_consume_consume {
        last_x: s.get_consume_consume_sv_last_x(),
      };
      if s.missing() {
        out.report(crate::Event::CheckSkipped { thread: "consume_consume", check: "IEP_Post" });
      } else if !crate::gumbox::consume_consume_GUMBOX::initialize_IEP_Post(
        post_consume_consume.last_x) {
        out.report(crate::Event::IepPostViolation { thread: "consume_consume", post: &post_consume_consume });
      }
    }
  }

  /// `prev` has completed a dispatch: check its CEP_Post against the pre-state
  /// saved when it was dispatched.
  pub fn on_complete<V: SystemView, S: ViolationSink>(&mut self, prev: crate::Thread, s: &mut V, out: &mut S) {
    match prev {
      crate::Thread::gen_gen => {
        s.focus(Some(crate::Thread::gen_gen));
        let post = PostState_gen_gen {
          api_outstruct: s.get_gen_gen_outstruct(),
        };
        if s.missing() {
          out.report(crate::Event::CheckSkipped { thread: "gen_gen", check: "CEP_Post" });
        } else if let Some(pre) = &self.pre_gen_gen {
          if !crate::gumbox::gen_gen_GUMBOX::compute_CEP_Post(
            post.api_outstruct) {
            out.report(crate::Event::CepPostViolation { thread: "gen_gen", pre: pre, post: &post });
          }
        } else {
          out.report(crate::Event::CepPostSkipped { thread: "gen_gen" });
        }
      }
      crate::Thread::splitter_splitter => {
        s.focus(Some(crate::Thread::splitter_splitter));
        let post = PostState_splitter_splitter {
          api_xfield: s.get_splitter_splitter_xfield(),
          api_yfield: s.get_splitter_splitter_yfield(),
        };
        if s.missing() {
          out.report(crate::Event::CheckSkipped { thread: "splitter_splitter", check: "CEP_Post" });
        } else if let Some(pre) = &self.pre_splitter_splitter {
          if !crate::gumbox::splitter_splitter_GUMBOX::compute_CEP_Post(
            pre.api_instruct, post.api_xfield, post.api_yfield) {
            out.report(crate::Event::CepPostViolation { thread: "splitter_splitter", pre: pre, post: &post });
          }
        } else {
          out.report(crate::Event::CepPostSkipped { thread: "splitter_splitter" });
        }
      }
      crate::Thread::incx_incx => {
        s.focus(Some(crate::Thread::incx_incx));
        let post = PostState_incx_incx {
          api_outxfield: s.get_incx_incx_outxfield(),
        };
        if s.missing() {
          out.report(crate::Event::CheckSkipped { thread: "incx_incx", check: "CEP_Post" });
        } else if let Some(pre) = &self.pre_incx_incx {
          if !crate::gumbox::incx_incx_GUMBOX::compute_CEP_Post(
            pre.api_inxfield, post.api_outxfield) {
            out.report(crate::Event::CepPostViolation { thread: "incx_incx", pre: pre, post: &post });
          }
        } else {
          out.report(crate::Event::CepPostSkipped { thread: "incx_incx" });
        }
      }
      crate::Thread::clampx_clampx => {
        s.focus(Some(crate::Thread::clampx_clampx));
        let post = PostState_clampx_clampx {
          api_outxfield: s.get_clampx_clampx_outxfield(),
        };
        if s.missing() {
          out.report(crate::Event::CheckSkipped { thread: "clampx_clampx", check: "CEP_Post" });
        } else if let Some(pre) = &self.pre_clampx_clampx {
          if !crate::gumbox::clampx_clampx_GUMBOX::compute_CEP_Post(
            pre.api_inxfield, post.api_outxfield) {
            out.report(crate::Event::CepPostViolation { thread: "clampx_clampx", pre: pre, post: &post });
          }
        } else {
          out.report(crate::Event::CepPostSkipped { thread: "clampx_clampx" });
        }
      }
      crate::Thread::decy_decy => {
        s.focus(Some(crate::Thread::decy_decy));
        let post = PostState_decy_decy {
          api_outyfield: s.get_decy_decy_outyfield(),
        };
        if s.missing() {
          out.report(crate::Event::CheckSkipped { thread: "decy_decy", check: "CEP_Post" });
        } else if let Some(pre) = &self.pre_decy_decy {
          if !crate::gumbox::decy_decy_GUMBOX::compute_CEP_Post(
            pre.api_inyfield, post.api_outyfield) {
            out.report(crate::Event::CepPostViolation { thread: "decy_decy", pre: pre, post: &post });
          }
        } else {
          out.report(crate::Event::CepPostSkipped { thread: "decy_decy" });
        }
      }
      crate::Thread::merger_merger => {
        s.focus(Some(crate::Thread::merger_merger));
        let post = PostState_merger_merger {
          api_outstruct: s.get_merger_merger_outstruct(),
        };
        if s.missing() {
          out.report(crate::Event::CheckSkipped { thread: "merger_merger", check: "CEP_Post" });
        } else if let Some(pre) = &self.pre_merger_merger {
          if !crate::gumbox::merger_merger_GUMBOX::compute_CEP_Post(
            pre.api_inxfield, pre.api_inyfield, post.api_outstruct) {
            out.report(crate::Event::CepPostViolation { thread: "merger_merger", pre: pre, post: &post });
          }
        } else {
          out.report(crate::Event::CepPostSkipped { thread: "merger_merger" });
        }
      }
      crate::Thread::consume_consume => {
        s.focus(Some(crate::Thread::consume_consume));
        let post = PostState_consume_consume {
          last_x: s.get_consume_consume_sv_last_x(),
        };
        if s.missing() {
          out.report(crate::Event::CheckSkipped { thread: "consume_consume", check: "CEP_Post" });
        } else if let Some(pre) = &self.pre_consume_consume {
          if !crate::gumbox::consume_consume_GUMBOX::compute_CEP_Post(
            pre.In_last_x, post.last_x, pre.api_instruct) {
            out.report(crate::Event::CepPostViolation { thread: "consume_consume", pre: pre, post: &post });
          }
        } else {
          out.report(crate::Event::CepPostSkipped { thread: "consume_consume" });
        }
      }
    }
  }

  /// Drops every saved pre-state, so each thread's next completion is skipped rather
  /// than checked against a dispatch it no longer describes -- after a dispatch went
  /// unobserved, or a thread overran its slot.
  pub fn forget(&mut self) {
    self.pre_gen_gen = None;
    self.pre_splitter_splitter = None;
    self.pre_incx_incx = None;
    self.pre_clampx_clampx = None;
    self.pre_decy_decy = None;
    self.pre_merger_merger = None;
    self.pre_consume_consume = None;
  }

  /// `next` is about to be dispatched: save its pre-state and check its CEP_Pre.
  pub fn on_dispatch<V: SystemView, S: ViolationSink>(&mut self, next: crate::Thread, s: &mut V, out: &mut S) {
    match next {
      crate::Thread::gen_gen => {
        s.focus(Some(crate::Thread::gen_gen));
        let pre = PreState_gen_gen {
        };
        if s.missing() {
          // no pre-state to hold the completion to, and no CEP_Pre that failed
          out.report(crate::Event::CheckSkipped { thread: "gen_gen", check: "CEP_Pre" });
          self.pre_gen_gen = None;
          self.pre_ok_gen_gen = true;
        } else {
          self.pre_ok_gen_gen = true;
          self.pre_gen_gen = Some(pre);
        }
      }
      crate::Thread::splitter_splitter => {
        s.focus(Some(crate::Thread::splitter_splitter));
        let pre = PreState_splitter_splitter {
          api_instruct: s.get_gen_gen_outstruct(),
        };
        if s.missing() {
          // no pre-state to hold the completion to, and no CEP_Pre that failed
          out.report(crate::Event::CheckSkipped { thread: "splitter_splitter", check: "CEP_Pre" });
          self.pre_splitter_splitter = None;
          self.pre_ok_splitter_splitter = true;
        } else {
          if !crate::gumbox::splitter_splitter_GUMBOX::compute_CEP_Pre(
            pre.api_instruct) {
            out.report(crate::Event::CepPreViolation { thread: "splitter_splitter", pre: &pre });
            self.pre_ok_splitter_splitter = false;
          } else {
            self.pre_ok_splitter_splitter = true;
          }
          self.pre_splitter_splitter = Some(pre);
        }
      }
      crate::Thread::incx_incx => {
        s.focus(Some(crate::Thread::incx_incx));
        let pre = PreState_incx_incx {
          api_inxfield: s.get_splitter_splitter_xfield(),
        };
        if s.missing() {
          // no pre-state to hold the completion to, and no CEP_Pre that failed
          out.report(crate::Event::CheckSkipped { thread: "incx_incx", check: "CEP_Pre" });
          self.pre_incx_incx = None;
          self.pre_ok_incx_incx = true;
        } else {
          if !crate::gumbox::incx_incx_GUMBOX::compute_CEP_Pre(
            pre.api_inxfield) {
            out.report(crate::Event::CepPreViolation { thread: "incx_incx", pre: &pre });
            self.pre_ok_incx_incx = false;
          } else {
            self.pre_ok_incx_incx = true;
          }
          self.pre_incx_incx = Some(pre);
        }
      }
      crate::Thread::clampx_clampx => {
        s.focus(Some(crate::Thread::clampx_clampx));
        let pre = PreState_clampx_clampx {
          api_inxfield: s.get_incx_incx_outxfield(),
        };
        if s.missing() {
          // no pre-state to hold the completion to, and no CEP_Pre that failed
          out.report(crate::Event::CheckSkipped { thread: "clampx_clampx", check: "CEP_Pre" });
          self.pre_clampx_clampx = None;
          self.pre_ok_clampx_clampx = true;
        } else {
          self.pre_ok_clampx_clampx = true;
          self.pre_clampx_clampx = Some(pre);
        }
      }
      crate::Thread::decy_decy => {
        s.focus(Some(crate::Thread::decy_decy));
        let pre = PreState_decy_decy {
          api_inyfield: s.get_splitter_splitter_yfield(),
        };
        if s.missing() {
          // no pre-state to hold the completion to, and no CEP_Pre that failed
          out.report(crate::Event::CheckSkipped { thread: "decy_decy", check: "CEP_Pre" });
          self.pre_decy_decy = None;
          self.pre_ok_decy_decy = true;
        } else {
          if !crate::gumbox::decy_decy_GUMBOX::compute_CEP_Pre(
            pre.api_inyfield) {
            out.report(crate::Event::CepPreViolation { thread: "decy_decy", pre: &pre });
            self.pre_ok_decy_decy = false;
          } else {
            self.pre_ok_decy_decy = true;
          }
          self.pre_decy_decy = Some(pre);
        }
      }
      crate::Thread::merger_merger => {
        s.focus(Some(crate::Thread::merger_merger));
        let pre = PreState_merger_merger {
          api_inxfield: s.get_clampx_clampx_outxfield(),
          api_inyfield: s.get_decy_decy_outyfield(),
        };
        if s.missing() {
          // no pre-state to hold the completion to, and no CEP_Pre that failed
          out.report(crate::Event::CheckSkipped { thread: "merger_merger", check: "CEP_Pre" });
          self.pre_merger_merger = None;
          self.pre_ok_merger_merger = true;
        } else {
          self.pre_ok_merger_merger = true;
          self.pre_merger_merger = Some(pre);
        }
      }
      crate::Thread::consume_consume => {
        s.focus(Some(crate::Thread::consume_consume));
        let pre = PreState_consume_consume {
          In_last_x: s.get_consume_consume_sv_last_x(),
          api_instruct: s.get_merger_merger_outstruct(),
        };
        if s.missing() {
          // no pre-state to hold the completion to, and no CEP_Pre that failed
          out.report(crate::Event::CheckSkipped { thread: "consume_consume", check: "CEP_Pre" });
          self.pre_consume_consume = None;
          self.pre_ok_consume_consume = true;
        } else {
          if !crate::gumbox::consume_consume_GUMBOX::compute_CEP_Pre(
            pre.In_last_x, pre.api_instruct) {
            out.report(crate::Event::CepPreViolation { thread: "consume_consume", pre: &pre });
            self.pre_ok_consume_consume = false;
          } else {
            self.pre_ok_consume_consume = true;
          }
          self.pre_consume_consume = Some(pre);
        }
      }
    }
  }

  /// Whether `t`'s CEP_Pre failed at its latest dispatch check -- the sender did not
  /// meet `t`'s contract.  A host that rejects such a dispatch (the test controller)
  /// asks this after `on_dispatch`.
  pub fn pre_failed(&self, t: crate::Thread) -> bool {
    match t {
      crate::Thread::gen_gen => !self.pre_ok_gen_gen,
      crate::Thread::splitter_splitter => !self.pre_ok_splitter_splitter,
      crate::Thread::incx_incx => !self.pre_ok_incx_incx,
      crate::Thread::clampx_clampx => !self.pre_ok_clampx_clampx,
      crate::Thread::decy_decy => !self.pre_ok_decy_decy,
      crate::Thread::merger_merger => !self.pre_ok_merger_merger,
      crate::Thread::consume_consume => !self.pre_ok_consume_consume,
    }
  }
}
